// src/pages/CreerCours.jsx
import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './CreerCours.css';

function CreerCours() {
  const [formData, setFormData] = useState({
    titre: '',
    description: '',
    matiere: '',
    niveau: 'débutant',
    prix: 0,
    estPublic: true,
    image: null
  });
  const [isLoading, setIsLoading] = useState(false);
  const [imagePreview, setImagePreview] = useState(null);
  const navigate = useNavigate();

  const handleInputChange = (e) => {
    const { name, value, type, checked, files } = e.target;
    
    if (type === 'file') {
      const file = files[0];
      setFormData(prev => ({
        ...prev,
        image: file
      }));

      // Aperçu de l'image
      if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setImagePreview(reader.result);
        };
        reader.readAsDataURL(file);
      } else {
        setImagePreview(null);
      }
    } else if (type === 'checkbox') {
      setFormData(prev => ({
        ...prev,
        [name]: checked
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: value
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    const token = localStorage.getItem('token');
    if (!token) {
      alert('Vous devez être connecté pour créer un cours');
      navigate('/login');
      return;
    }

    try {
      // Créer FormData pour gérer les fichiers
      const submitData = new FormData();
      submitData.append('titre', formData.titre);
      submitData.append('description', formData.description);
      submitData.append('matiere', formData.matiere);
      submitData.append('niveau', formData.niveau);
      submitData.append('prix', formData.prix);
      submitData.append('estPublic', formData.estPublic);
      if (formData.image) {
        submitData.append('image', formData.image);
      }

      const res = await axios.post('http://localhost:5000/api/cours', submitData, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      alert('Cours créé avec succès !');
      navigate('/dashboard-prof');
      
    } catch (err) {
      console.error('Erreur création cours:', err);
      alert(err.response?.data?.msg || 'Erreur lors de la création du cours');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    if (window.confirm('Voulez-vous vraiment annuler ? Les modifications seront perdues.')) {
      navigate('/dashboard-prof');
    }
  };

  return (
    <div className="creer-cours-container">
      <div className="creer-cours-card">
        <div className="creer-cours-header">
          <button className="back-btn" onClick={handleCancel}>
            ← Retour
          </button>
          <h1>Créer un nouveau cours</h1>
          <p>Remplissez les informations pour créer votre cours</p>
        </div>

        <form onSubmit={handleSubmit} className="creer-cours-form">
          <div className="form-sections">
            {/* Section Informations de base */}
            <div className="form-section">
              <h2>Informations de base</h2>
              
              <div className="form-group">
                <label htmlFor="titre">Titre du cours *</label>
                <input
                  id="titre"
                  type="text"
                  name="titre"
                  value={formData.titre}
                  onChange={handleInputChange}
                  placeholder="Ex: Mathématiques Avancées, Physique Quantique..."
                  required
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label htmlFor="description">Description *</label>
                <textarea
                  id="description"
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  placeholder="Décrivez le contenu de votre cours, les objectifs d'apprentissage, etc."
                  required
                  rows="4"
                  className="form-textarea"
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="matiere">Matière *</label>
                  <select
                    id="matiere"
                    name="matiere"
                    value={formData.matiere}
                    onChange={handleInputChange}
                    required
                    className="form-select"
                  >
                    <option value="">Sélectionnez une matière</option>
                    <option value="mathematiques">Mathématiques</option>
                    <option value="physique">Physique</option>
                    <option value="chimie">Chimie</option>
                    <option value="informatique">Informatique</option>
                    <option value="biologie">Biologie</option>
                    <option value="francais">Français</option>
                    <option value="anglais">Anglais</option>
                    <option value="histoire">Histoire</option>
                    <option value="philosophie">Philosophie</option>
                    <option value="autres">Autres</option>
                  </select>
                </div>

                <div className="form-group">
                  <label htmlFor="niveau">Niveau *</label>
                  <select
                    id="niveau"
                    name="niveau"
                    value={formData.niveau}
                    onChange={handleInputChange}
                    required
                    className="form-select"
                  >
                    <option value="débutant">Débutant</option>
                    <option value="intermédiaire">Intermédiaire</option>
                    <option value="avancé">Avancé</option>
                    <option value="expert">Expert</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Section Image et paramètres */}
            <div className="form-section">
              <h2>Image et paramètres</h2>
              
              <div className="form-group">
                <label>Image du cours</label>
                <div className="image-upload-container">
                  <div className="image-preview">
                    {imagePreview ? (
                      <img src={imagePreview} alt="Aperçu du cours" />
                    ) : (
                      <div className="image-placeholder">
                        <span>📚</span>
                        <p>Aucune image sélectionnée</p>
                      </div>
                    )}
                  </div>
                  <label htmlFor="image-upload" className="image-upload-btn">
                    📷 Choisir une image
                  </label>
                  <input
                    id="image-upload"
                    type="file"
                    name="image"
                    accept="image/*"
                    onChange={handleInputChange}
                    className="image-input"
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="prix">Prix (DH)</label>
                  <input
                    id="prix"
                    type="number"
                    name="prix"
                    value={formData.prix}
                    onChange={handleInputChange}
                    min="0"
                    step="10"
                    placeholder="0"
                    className="form-input"
                  />
                  <small>Laissez 0 pour un cours gratuit</small>
                </div>

                <div className="form-group">
                  <label className="checkbox-label">
                    <input
                      type="checkbox"
                      name="estPublic"
                      checked={formData.estPublic}
                      onChange={handleInputChange}
                      className="checkbox-input"
                    />
                    <span className="checkmark"></span>
                    Cours public
                  </label>
                  <small>Si désactivé, le cours sera privé et accessible par lien uniquement</small>
                </div>
              </div>
            </div>

            {/* Section Contenu du cours */}
            <div className="form-section">
              <h2>Structure du cours</h2>
              
              <div className="modules-container">
                <div className="module-item">
                  <h4>Module 1: Introduction</h4>
                  <p>Ajoutez vos chapitres et leçons après la création du cours</p>
                </div>
                <div className="add-module-btn">
                  + Ajouter un module
                </div>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="form-actions">
            <button 
              type="button" 
              className="cancel-btn"
              onClick={handleCancel}
            >
              Annuler
            </button>
            <button 
              type="submit" 
              className="submit-btn"
              disabled={isLoading || !formData.titre || !formData.description || !formData.matiere}
            >
              {isLoading ? (
                <>
                  <span className="spinner"></span>
                  Création en cours...
                </>
              ) : (
                'Créer le cours'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default CreerCours;
